from pathlib import Path
import json,numpy as np
R=Path(__file__).resolve().parents[1];A=R/'artifacts/bilin18_tensor_decomposition';stem='bilin18_l17_head_specific_source_spaces';j=json.loads((A/f'{stem}.json').read_text());z=np.load(A/f'{stem}_rows.npz');e=z['errors'].reshape(2,6,9,12,128,2);d=z['effects'].reshape(2,9,12,128,2);assert np.isfinite(e).all() and all(j['numerical_gates'].values());rec=1-e.sum((3,4))/d.sum((2,3))[:,None,:,:];others=np.array([i for i in range(9) if i!=6]);ee=e[...,1];dd=d[...,1]
def contrast(r):return np.array([r[0,0,others].mean(),r[1,0,others].mean(),(r[0,0,others]-r[0,3,others]).mean(),(r[1,0,others]-r[1,3,others]).mean()])
pt=contrast(rec[...,1]);assert np.allclose(pt,contrast(1-ee.sum((3,4))/dd.sum((2,3))[:,None,:]));rng=np.random.default_rng(j['config']['bootstrap_seed']);boot=[]
